(function(root){'use strict';
function merge(a,b){const out={...a};for(const [k,r] of Object.entries(b||{})){const old=out[k];if(!old||r.time>old.time||(r.time===old.time&&r.device>old.device))out[k]=r}return out}
function flatten(state){const out={};for(const kind of ['saved','hidden'])for(const [key,value] of Object.entries(state[kind]||{}))out[JSON.stringify([kind,key])]={kind,key,value};for(const [agent,h] of Object.entries(state.hauls||{})){for(const [key,value] of Object.entries(h.items||{}))out[JSON.stringify(['item',agent,key])]={kind:'item',agent,key,value};for(const field of ['shipping','packing','domestic','fees','taxes','costsStale'])if(h[field]!==undefined)out[JSON.stringify(['cost',agent,field])]={kind:'cost',agent,field,value:h[field]}}return out}
function expand(records){const state={saved:{},hidden:{},hauls:{}};for(const r of Object.values(records||{})){if(r.value===null)continue;if(['saved','hidden'].includes(r.kind)){if(typeof r.key!=='string'||!r.value?.key||!Array.isArray(r.value.offers)||!r.value.offers.every(o=>/^https?:\/\//.test(o.url)))continue;state[r.kind][r.key]=r.value}else if(['item','cost'].includes(r.kind)&&typeof r.agent==='string'&&r.agent!=='__proto__'){const h=state.hauls[r.agent]??={items:{},shipping:'',packing:'',domestic:'',fees:'',taxes:''};if(r.kind==='item'&&r.value?.offer&&root.FindsModel?.agent(r.value.offer)?.id===r.agent&&Number.isInteger(r.value.quantity)&&r.value.quantity>0&&r.value.quantity<=99)h.items[r.key]=r.value;else if(r.kind==='cost'&&['shipping','packing','domestic','fees','taxes','costsStale'].includes(r.field))h[r.field]=r.value}}return state}
function start(options){const storage=localStorage,fetcher=options.fetch||fetch,api='https://api.github.com/repos/davXdash/repo/contents/user-state.enc.json',branch='user-data',device=storage.getItem('finds-device-id')||crypto.randomUUID();storage.setItem('finds-device-id',device);let records;try{records=JSON.parse(storage.getItem('finds-sync-records-v1'))||{}}catch{records={}}let baseline={},token=storage.getItem('finds-github-token-v1')||'',timer,running=false,again=false,applying=false,clock=Date.now();const b64=b=>btoa(Array.from(new Uint8Array(b),v=>String.fromCharCode(v)).join('')),bytes=s=>Uint8Array.from(atob(s),v=>v.charCodeAt(0));
 const persist=()=>storage.setItem('finds-sync-records-v1',JSON.stringify(records));
 const status=t=>options.onStatus(t);
 async function key(salt){return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},options.material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
 async function encrypt(data){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),raw=new TextEncoder().encode(JSON.stringify(data)),gzip=await new Response(new Blob([raw]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer(),ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv},await key(salt),gzip);return JSON.stringify({version:1,compression:'gzip',salt:b64(salt),iv:b64(iv),ciphertext:b64(ciphertext)})}
 async function decrypt(payload){if(payload.version!==1)throw Error('format');const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(payload.iv)},await key(bytes(payload.salt)),bytes(payload.ciphertext)),clear=await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('gzip'))).text(),data=JSON.parse(clear);if(data.schema!==1||!data.records)throw Error('format');return data.records}
 function capture(schedule=true){if(applying)return;const now=flatten(options.getState());for(const id of new Set([...Object.keys(baseline),...Object.keys(now)])){if(JSON.stringify(now[id])!==JSON.stringify(baseline[id])){clock=Math.max(Date.now(),clock+1,...Object.values(records).map(r=>Number(r.time)||0));records[id]={...(now[id]||baseline[id]),value:now[id]?.value??null,time:clock,device}}}baseline=now;persist();if(schedule&&token){clearTimeout(timer);timer=setTimeout(sync,1600)}}
 async function request(method,body){const response=await fetcher(api+(method==='GET'?'?ref='+branch:''),{method,cache:'no-store',headers:{'Accept':'application/vnd.github+json','Authorization':'Bearer '+token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});if(method==='GET'&&response.status===404)return null;if(!response.ok){const error=Error('request');error.status=response.status;throw error}return response.json()}
 async function sync(){if(!token){status('Nur auf diesem Gerät · GitHub noch nicht verbunden');return}if(running){again=true;return}running=true;status('Listen werden abgeglichen …');try{capture(false);for(let attempt=0;attempt<3;attempt++){const remote=await request('GET'),remoteRecords=remote?await decrypt(JSON.parse(new TextDecoder().decode(bytes(remote.content.replace(/\s/g,''))))):{};records=merge(remoteRecords,records);persist();applying=true;options.applyState(expand(records));baseline=flatten(options.getState());applying=false;const canonical=r=>JSON.stringify(Object.entries(r).sort(([a],[b])=>a.localeCompare(b)));if(canonical(remoteRecords)===canonical(records))break;const encrypted=await encrypt({schema:1,records});if(encrypted.length>900000)throw Error('size');try{await request('PUT',{message:'Sync encrypted personal lists [skip ci]',branch,content:b64(new TextEncoder().encode(encrypted)),...(remote?.sha?{sha:remote.sha}:{})});break}catch(e){if(e.status!==409||attempt===2)throw e}}status('Synchronisiert · '+new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}));}catch(e){applying=false;status(e.status===401||e.status===403?'GitHub-Verbindung prüfen · Änderungen lokal gesichert':e.message==='size'?'Synchronisierung zu groß · Änderungen lokal gesichert':'Abgleich gerade fehlgeschlagen · Änderungen lokal gesichert')}finally{running=false;if(again){again=false;clearTimeout(timer);timer=setTimeout(sync,1600)}}}
 baseline=flatten(expand(records));capture(false);status(token?'GitHub verbunden · Abgleich startet':'Nur auf diesem Gerät · GitHub noch nicht verbunden');if(token)sync();const poll=setInterval(()=>{if(!document.hidden&&token)sync()},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&token)sync()});window.addEventListener('online',sync);return {capture,sync,stop(){clearInterval(poll);clearTimeout(timer)},connect(value){token=value.trim();storage.setItem('finds-github-token-v1',token);return sync()},disconnect(){token='';storage.removeItem('finds-github-token-v1');status('Nur auf diesem Gerät · GitHub getrennt')}}
}
const api={merge,flatten,expand,start};root.FindsSync=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
